static __forceinline ULONGLONG rsc_sw_now100ns(VOID)
{
    return KeQueryInterruptTime();
}

static VOID rsc_sw_init_node_defaults(VOID)
{
    RtlZeroMemory(g_rsc_sw_nodes, sizeof(g_rsc_sw_nodes));
    for (ULONG i = 0; i < RSCSW_NODE_CAPACITY; i++) {
        g_rsc_sw_nodes[i].subsystem_id = i;
        g_rsc_sw_nodes[i].present = 1;
        g_rsc_sw_nodes[i].last_status = STATUS_SUCCESS;
        (VOID) RtlStringCchCopyA(g_rsc_sw_nodes[i].name, RTL_NUMBER_OF(g_rsc_sw_nodes[i].name),
                                 g_rsc_sw_names[i]);
    }
}

