                if (score == 0u)
                    continue;

                ULONG route_cnt = 0u;
                ULONG peak_bandwidth_mb = 0u;
                ULONG subsystem_mask = rsc_sw_lookup_subsystem_mask_for_icb_id(id, TRUE, &route_cnt,
                                                                               &peak_bandwidth_mb);

                rsc_sw_lookup_record_match(&local, RSCSW_LOOKUP_KIND_ICB_MASTER, id,
                                           g_rsc_sw_icb_master_names[id], subsystem_mask, score,
                                           route_cnt, peak_bandwidth_mb);
