    if (semantic_coverage_permille < 1000u)
        drift += (1000u - semantic_coverage_permille) / 2u;
    drift += dependency_risk_permille / 4u;
    drift += topology_pressure_permille / 5u;

    if (aop_subsystem_type == 0x5u && aop_state >= 0x2u)
        drift += 30u;
    if (aop_subsystem_type == 0xFFFFFFFFu && aop_state != 0x0u)
        drift += 40u;
    if (arc_res_type == 0xAu && power_domain_action != 0x0u)
        drift += 35u;
    if (arc_res_type == 0x4u && clock_action == 0x2u && clock_res == 0x1u)
        drift += 25u;
    if (cmd_db_slave_id == 0x7FFFFFFu && cmd_db_error == 0x0u)
        drift += 45u;
    if (cmd_db_slave_id == 0x0u && cmd_db_lookup_status == 0x2u && cmd_db_error == 0x0u)
        drift += 40u;
    if (cmd_db_query_type == 0x2u && cmd_db_error == 0x0u)
        drift += 35u;
    if (clock_driver_type == 0x4u && clock_action != 0x0u)
        drift += 20u;
    if (clock_driver_type == 0x1u && clock_action == 0x4u && clock_freq >= 0x20u)
        drift += 30u;
    if (clock_config_param_type == 0x32u && clock_action == 0x2u)
        drift += 25u;
    if (clock_config_param_type == 0x4u && clock_driver_type == 0x4u)
        drift += 20u;
    if (pdc_drv_type == 0xFFFFFFFFu && pdc_status == 0x0u)
        drift += 50u;
